// Allowlisted share encoding for the junk removal bid calculator. A shared
// URL must reconstruct the same job the sender saw — silently dropping a
// pile's weight, the dump-fee rate, or the target margin is how two people
// compute different profits from the "same" link. Only these keys ride in
// the hash; anything else is ignored so a crafted fragment cannot inject
// unexpected behavior.

export const SHARE_FIELDS = Object.freeze([
  'truckCapacityCubicYards', 'dumpFeePerTon', 'dumpMinimum', 'surchargeRate',
  'onSiteHours', 'stairsFlights', 'minutesPerFlight', 'longCarryMinutes',
  'oneWayMinutes', 'dumpMinutes', 'crewSize', 'hourlyWage', 'burdenRate',
  'fuelPerJob', 'otherJobCost', 'overheadRate', 'targetMargin', 'minimumCharge',
  'proposedPrice',
]);

// `name` travels as the material preset's own label — `addPileRow` matches
// it back to a preset, or to "Other material" when nothing matches — so a
// pile priced with a preset the sender edited restores as that preset, not
// as whichever preset happens to sit first in the list. `unit` and
// `cubicYardsEach` are not carried: they are looked up from the preset at
// read time (`readPiles()`), never stored on the row itself.
const PILE_KEYS = Object.freeze(['name', 'quantity', 'lbsPerUnit', 'specialFeeEach']);

function pick(object, keys) {
  const out = {};
  for (const key of keys) {
    if (object[key] !== undefined) out[key] = object[key];
  }
  return out;
}

export function encodeShare(input) {
  const payload = pick(input || {}, SHARE_FIELDS);
  if (Array.isArray(input?.piles)) {
    payload.piles = input.piles.map(row => pick(row || {}, PILE_KEYS));
  }
  return encodeURIComponent(JSON.stringify(payload));
}

export function decodeShare(fragment) {
  if (!fragment) return null;
  const raw = String(fragment).replace(/^#/, '');
  if (!raw) return null;
  let parsed;
  try {
    parsed = JSON.parse(decodeURIComponent(raw));
  } catch {
    return null;
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null;
  const payload = pick(parsed, SHARE_FIELDS);
  if (Array.isArray(parsed.piles)) {
    payload.piles = parsed.piles
      .map(row => pick(row || {}, PILE_KEYS))
      .filter(row => Object.keys(row).length > 0);
  }
  if (Object.keys(payload).length === 0) return null;
  return payload;
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores the
// address, the load, the dump rate, the wage, the price, or any other bid
// input, and it never leaves the device — a hauler's pricing is exactly the
// sort of thing that must not be transmitted anywhere.
function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'bid_calculated') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  const today = new Date().toISOString().slice(0, 10);
  const current = JSON.parse(storage.getItem('junk-removal-bid-usage') || '{}');
  current[event] = (current[event] || 0) + 1;
  current.last_day = today;
  storage.setItem('junk-removal-bid-usage', JSON.stringify(current));
}

// The opt-out choice is kept in its own key, not in the counters:
// opting out *removes* the counters, so a flag stored inside them would
// be deleted by the very act it records. `recordUsage` above consults it
// directly as well as taking the caller's argument -- a stored preference
// that only one line of page wiring reads is one line away from being
// forgotten, which is the defect this change exists to fix.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem('junk-removal-bid-usage-opt-out') === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem
  // that throws on a full quota skips the delete entirely, and the
  // visitor gets neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem('junk-removal-bid-usage'); } catch { /* storage is optional */ }
    try { storage.setItem('junk-removal-bid-usage-opt-out', '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem('junk-removal-bid-usage-opt-out'); } catch { /* storage is optional */ }
  }
}
